const assertUuid = (value, field) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error(`Invalid ${field}: ${value}`);
  }
  return text;
};

const body = $input.first().json.body ?? $input.first().json ?? {};
return [{ json: { user_id: assertUuid(body.user_id, 'user_id') } }];

// Si el borrado en Drive falla se ignora: la referencia en BD ya está limpia
// y el archivo queda huérfano, no roto.
const cleared = $('Limpiar en users').first().json;

if (!cleared || cleared.error || !cleared.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo eliminar la firma.' } } }];
}

return [{ json: { statusCode: 200, body: { success: true, user_id: cleared.id } } }];
